/* Timeline */
.timeline {
	position: relative;
	display: block;
	margin: 0;
	padding: 10px 0;
	list-style: none;
	&:after {
		content: " ";
		display: table;
		clear: both;
	}
	&:before {
		content: " ";
		display: table;
	}
	>li {
		list-style: none;
		&:nth-child(even) {
			float: left;
			clear: left;
		}
		&:nth-child(odd) {
			float: right;
			clear: right;
			//margin-top: 20px;
		}
	}
	.media {
		border-bottom: 1px solid #eee;
		font-size: 13px;
		p {
			font-size: 13px;
		}
		&:last-child {
			border-bottom: 0;
		}
	}
}

.timeline-line+.timeline-item {
	margin-top: -20px;
}
.timeline-group {
	display: block;
	position: relative;
	margin: 20px 0;
	text-align: center;
	float: none !important;
	z-index: 1;
}
.timeline-poster {
	margin-top: -20px;
	.btn-link {
		color: #a1aab0;
		&:active {
			color: #3e5771;
		}
		&:focus {
			color: #3e5771;
		}
		&:hover {
			color: #3e5771;
		}
	}
	.btn-link.active {
		color: #3e5771;
	}
}

#timeline.timeline-center{
